{"cards": [{"node_code": "N_ac3d5f8754b73797", "definition": "研究土体在反复动力荷载作用下产生的不可恢复体积压缩与竖向沉降，涵盖震陷机理、影响因素、计算方法及工程防治措施。", "boundary": "本节点聚焦于非饱和或饱和土在循环荷载下的累积塑性变形导致的永久沉降。边界包括震陷判别标准、震陷量估算模型及不同土类（如粉土、砂土）的震陷特性。不包含由孔隙水压力累积导致的土体强度丧失（归入液化），也不包含静力荷载下的固结沉降（归入土的变形与沉降）。", "includes": ["震陷机理与累积塑性变形理论", "震陷判别标准与震陷量计算方法", "不同土类（粉土、砂土等）的震陷特性及防治"], "excludes": ["土体液化导致的强度丧失与流动（归入液化）", "静力荷载下的固结沉降与弹性变形（归入土的变形与沉降）"], "sibling_distinctions": [{"other_code": "N_65660aea2044fbc1", "rule": "本节点侧重土体体积压缩导致的永久沉降（震陷），兄弟节点侧重孔隙水压力累积导致的强度丧失与流动（液化）。"}, {"other_code": "N_3bee1699e2323a59", "rule": "本节点侧重循环荷载下的变形累积效应，兄弟节点侧重循环荷载下的抗剪强度衰减与破坏。"}], "cross_boundary_rule": "涉及地震作用下地基沉降，若主要关注体积压缩与永久变形，主挂载于本节点；若主要关注强度丧失与流动，主挂载于液化。"}, {"node_code": "N_cc3d67ce921a97f2", "definition": "研究土体在动力荷载下能量耗散特性，涵盖阻尼比的定义、测定方法、频率依赖性及其在动力响应分析中的应用。", "boundary": "本节点聚焦于土体动力参数中的阻尼特性，强调能量耗散机制。边界包括等效粘滞阻尼比、材料阻尼与辐射阻尼的区分，以及不同频率、应变幅值下阻尼比的变化规律。不包含动模量（刚度）的测定（归入动模量），也不包含结构本身的阻尼设计（归入结构抗震设计）。", "includes": ["土体阻尼比的定义与物理意义", "阻尼比的试验测定方法（如共振柱、动三轴）", "阻尼比随频率、应变幅值及应力水平的变化规律"], "excludes": ["土体动模量（刚度）的测定与理论（归入动模量）", "结构体系或基础结构的阻尼器设计与应用（归入结构抗震设计）"], "sibling_distinctions": [{"other_code": "N_4abb56472873158a", "rule": "本节点侧重能量耗散（阻尼），兄弟节点侧重刚度特性（动模量）。两者常同时测定但物理意义不同。"}], "cross_boundary_rule": "涉及土体动力参数，若侧重能量耗散与阻尼比，主挂载于本节点；若侧重刚度与模量，主挂载于动模量。"}, {"node_code": "N_3bee1699e2323a59", "definition": "研究土体在反复循环荷载作用下的抗剪强度特性，涵盖循环强度衰减、残余强度、强度比及循环破坏准则。", "boundary": "本节点聚焦于土体在循环荷载下的强度行为，强调强度随循环次数或应变幅值的衰减规律。边界包括循环三轴试验、循环强度比、残余强度及循环破坏判据。不包含循环荷载下的变形累积（归入震陷），也不包含静力荷载下的抗剪强度（归入土的抗剪强度）。", "includes": ["循环荷载下土体抗剪强度的衰减规律", "循环强度比、残余强度及循环破坏准则", "循环三轴试验方法与强度参数测定"], "excludes": ["循环荷载下的累积塑性变形与震陷（归入震陷）", "静力荷载下的抗剪强度准则与破坏（归入土的抗剪强度）"], "sibling_distinctions": [{"other_code": "N_ac3d5f8754b73797", "rule": "本节点侧重循环荷载下的强度衰减与破坏，兄弟节点侧重循环荷载下的变形累积与沉降。"}, {"other_code": "N_65660aea2044fbc1", "rule": "本节点侧重一般循环荷载下的强度特性，兄弟节点侧重特定条件下（如饱和砂土）孔隙水压力累积导致的强度完全丧失（液化）。"}], "cross_boundary_rule": "涉及循环荷载下土体破坏，若侧重强度衰减与残余强度，主挂载于本节点；若侧重孔隙水压力累积导致的液化，主挂载于液化。"}]}
